class Solution {
  public double myPow(double x, int n) {
    long power = n;
    if (power < 0) return 1.0 / fastPow(x, -power);
    return fastPow(x, power);
  }

  private double fastPow(double x, long power) {
    if (power == 0) return 1.0;
    double half = fastPow(x, power / 2);
    double squared = half * half;
    return power % 2 == 0 ? squared : squared * x;
  }
}

