  public List<String> generateParenthesis(int n) {
    List<String> answer = new ArrayList<>();
    Deque<State> stack = new ArrayDeque<>();
    stack.push(new State("", 0, 0));

    while (!stack.isEmpty()) {
      State current = stack.pop();
      if (current.value.length() == 2 * n) {
        answer.add(current.value);
        continue;
      }
      if (current.close < current.open) {
        stack.push(new State(current.value + ")", current.open, current.close + 1));
      }
      if (current.open < n) {
        stack.push(new State(current.value + "(", current.open + 1, current.close));
      }
    }

    return answer;
  }

  private static class State {
    String value;
    int open;
    int close;
