import java.util.*;

class Solution {
  public List<List<String>> solveNQueens(int n) {
    List<List<String>> answer = new ArrayList<>();
    int[] queenCol = new int[n];
    Arrays.fill(queenCol, -1);
    boolean[] cols = new boolean[n];
    boolean[] diag1 = new boolean[2 * n];
    boolean[] diag2 = new boolean[2 * n];
    int row = 0;
    int col = 0;

    while (row >= 0) {
      boolean placed = false;
      for (; col < n; col++) {
        int d1 = row - col + n;
        int d2 = row + col;
        if (cols[col] || diag1[d1] || diag2[d2]) continue;
        queenCol[row] = col;
        cols[col] = diag1[d1] = diag2[d2] = true;
        row++;
        col = 0;
        placed = true;
        break;
      }

      if (row == n) {
        answer.add(build(queenCol));
        row--;
        col = queenCol[row] + 1;
        remove(row, queenCol, cols, diag1, diag2, n);
      } else if (!placed) {
        row--;
        if (row >= 0) {
          col = queenCol[row] + 1;
          remove(row, queenCol, cols, diag1, diag2, n);
        }
      }
    }
    return answer;
  }

  private void remove(int row, int[] queenCol, boolean[] cols, boolean[] diag1, boolean[] diag2, int n) {
    int col = queenCol[row];
    cols[col] = false;
    diag1[row - col + n] = false;
    diag2[row + col] = false;
    queenCol[row] = -1;
  }

  private List<String> build(int[] queenCol) {
    List<String> board = new ArrayList<>();
    for (int col : queenCol) {
      char[] row = new char[queenCol.length];
      Arrays.fill(row, '.');
      row[col] = 'Q';
      board.add(new String(row));
    }
    return board;
  }
}

