class Solution {
  public void solveSudoku(char[][] board) {
    List<int[]> blanks = new ArrayList<>();
    boolean[][] rows = new boolean[9][10];
    boolean[][] cols = new boolean[9][10];
    boolean[][] boxes = new boolean[9][10];

    for (int r = 0; r < 9; r++) {
      for (int c = 0; c < 9; c++) {
        if (board[r][c] == '.') blanks.add(new int[] {r, c});
        else place(rows, cols, boxes, r, c, board[r][c] - '0', true);
      }
    }

    int[] nextDigit = new int[blanks.size()];
    Arrays.fill(nextDigit, 1);
    int index = 0;
    while (index >= 0 && index < blanks.size()) {
      int r = blanks.get(index)[0], c = blanks.get(index)[1];
      if (board[r][c] != '.') {
        place(rows, cols, boxes, r, c, board[r][c] - '0', false);
        board[r][c] = '.';
      }

      boolean placed = false;
      for (int d = nextDigit[index]; d <= 9; d++) {
        if (!rows[r][d] && !cols[c][d] && !boxes[box(r, c)][d]) {
          board[r][c] = (char) ('0' + d);
          place(rows, cols, boxes, r, c, d, true);
          nextDigit[index] = d + 1;
          index++;
          placed = true;
          break;
        }
      }
      if (!placed) {
        nextDigit[index] = 1;
        index--;
      }
    }
  }

  private void place(boolean[][] rows, boolean[][] cols, boolean[][] boxes,
      int r, int c, int d, boolean used) {
    rows[r][d] = used;
    cols[c][d] = used;
    boxes[box(r, c)][d] = used;
  }

  private int box(int r, int c) {
    return (r / 3) * 3 + c / 3;
  }
}

