  private boolean solve(char[][] board, List<int[]> blanks, int index,
      boolean[][] rows, boolean[][] cols, boolean[][] boxes) {
    if (index == blanks.size()) return true;

    int r = blanks.get(index)[0], c = blanks.get(index)[1];
