class Solution {
  private static final int[][] DIRS = {{1,0},{-1,0},{0,1},{0,-1}};

  public boolean exist(char[][] board, String word) {
    int rows = board.length, cols = board[0].length;
    for (int r = 0; r < rows; r++) {
      for (int c = 0; c < cols; c++) {
        if (board[r][c] != word.charAt(0)) continue;
        Deque<State> stack = new ArrayDeque<>();
        stack.push(new State(r, c, 0, 1L << (r * cols + c)));
        while (!stack.isEmpty()) {
          State cur = stack.pop();
          if (cur.index == word.length() - 1) return true;
          for (int[] dir : DIRS) {
            int nr = cur.row + dir[0], nc = cur.col + dir[1];
            int nextIndex = cur.index + 1;
            if (nr < 0 || nc < 0 || nr == rows || nc == cols) continue;
            long bit = 1L << (nr * cols + nc);
            if ((cur.used & bit) != 0 || board[nr][nc] != word.charAt(nextIndex)) continue;
            stack.push(new State(nr, nc, nextIndex, cur.used | bit));
          }
        }
      }
    }
    return false;
  }

  private static class State {
    int row, col, index;
    long used;
    State(int row, int col, int index, long used) {
      this.row = row;
      this.col = col;
      this.index = index;
      this.used = used;
    }
  }
